SET work_mem = '64kB';
EXPLAIN (ANALYZE, COSTS OFF)
SELECT * FROM log1 ORDER BY b;
-- Sort Method: external merge
--   Disk: 10744kB

SET work_mem = '64MB';
-- Sort Method: quicksort
--   Memory: 47445kB

RESET work_mem;

CREATE MATERIALIZED VIEW mv_umsatz AS
SELECT d.monat,
       SUM(f.umsatz) AS umsatz
FROM fakt_verkauf f
JOIN dim_datum d USING (datum_id)
GROUP BY d.monat;
-- 1 | 317.50   2 | 215.00

INSERT INTO fakt_verkauf
  VALUES (20260209,2,1,10,20.00);
SELECT * FROM mv_umsatz;
-- 2 | 215.00  (noch alt!)

REFRESH MATERIALIZED VIEW mv_umsatz;
-- 2 | 235.00
